def resolve(path, cwd, links):
    # Track the number of links followed
    link_count = 0
    max_links = 8

    # Make path absolute if it doesn't start with '/'
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    # Split the path into components
    components = path.split('/')

    # Start with root
    current = ''

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '/':
                continue  # Already at root
            else:
                current = '/'.join(current.split('/')[:-1])
                if current == '':
                    current = '/'
            continue

        # Append the component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[current]

            # Make target absolute if needed
            if not target.startswith('/'):
                # Target is relative to the directory containing the link
                link_dir = '/'.join(current.split('/')[:-1])
                if link_dir == '':
                    link_dir = '/'
                if link_dir == '/':
                    target = '/' + target
                else:
                    target = link_dir + '/' + target

            # Resolve the target recursively
            resolved = resolve(target, cwd, links)
            if resolved is None:
                return None

            current = resolved

    # Ensure no trailing slash (except for '/')
    if current == '':
        current = '/'
    elif current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

